		/**
		 * Returns a new populated Procedure
		 * 
		 * @return Procedure
		 */
		protected Procedure generateNewEntity() {
			Procedure entity = new Procedure( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),   new Date(),  null,  null,  null,  ProcedureStatus.values()[0] );
			
			return( entity );
		}

